        ChallengeRoutine.Task math=new ChallengeRoutine.Task("Math",1);String encoded=ChallengeRoutineJson.encode(new ChallengeRoutine(List.of(math))).toString();Instrumentation.ActivityMonitor monitor=i.addMonitor(RandomChallengePreviewActivity.class.getName(),null,false);RandomChallengePreviewActivity child;
